119	        BigDecimal targetPressure = station.pressureTargetMpa();
120	        BigDecimal rateBefore = state.currentInjectionRateMgM3();
121	        BigDecimal rateAfter;
122	        BigDecimal dose;
123	        if (state.injectionLocked()) {
124	            // 加注阀锁定中：加注指令以“维持、零加注量”下发，调压仍执行
125	            rateAfter = rateBefore;
126	            dose = BigDecimal.ZERO.setScale(3, RoundingMode.HALF_UP);
127	        } else {
128	            // 比例投加：联动后速率折算浓度回归目标浓度，本次加注量 = 流量 × 目标浓度
129	            rateAfter = station.targetConcentrationMgM3();
