26	
27	/**
28	 * 压力调节测试：恰等限值合格、超差联动、调压加注原子性、同刻并发唯一受理、幂等重放/异参409。
29	 */
30	class PressureServiceTest extends AbstractIntegrationTest {
31	
32	    private static final LocalDateTime T = LocalDate.of(2026, 9, 25).atTime(13, 0);
33	
34	    @Autowired
35	    private PressureService pressureService;
36	    @Autowired
37	    private LinkageTaskRepository linkageTaskRepository;
38	
39	    private PressureDetectRequest request(String requestId, LocalDateTime time, String pressure) {
40	        return new PressureDetectRequest("ST01", requestId, time,
41	                new BigDecimal(pressure), new BigDecimal("100"));
42	    }
43	
44	    @Test
45	    void pressureExactlyAtLimitsIsNormalAndNoLinkage() {
46	        PressureDetectResponse low = pressureService.detect(request("PR-LO", T, "0.3000"));
47	        assertEquals("NORMAL", low.grade(), "恰下限0.3000判合格");
48	        assertFalse(low.accepted());
49	        assertNull(low.taskId());
50	
51	        PressureDetectResponse high = pressureService.detect(request("PR-HI", T.plusMinutes(1), "0.5000"));
52	        assertEquals("NORMAL", high.grade(), "恰上限0.5000判合格");
53	        assertFalse(high.accepted());
54	        assertEquals(0, linkageTaskRepository.countByRequest("PR-HI"));
55	    }
56	
57	    @Test
58	    void highPressureTriggersAtomicPressureAndInjectionAdjustment() {
59	        PressureDetectResponse resp = pressureService.detect(request("PR-1", T, "0.6000"));
60	        assertEquals("HIGH", resp.grade());
61	        assertTrue(resp.accepted());
62	        assertNotNull(resp.taskId());
63	        assertEquals(0, new BigDecimal("0.6000").compareTo(resp.pressureBeforeMpa()));
64	        assertEquals(0, new BigDecimal("0.4000").compareTo(resp.pressureAfterMpa()), "调压回归目标0.4");
65	        assertEquals(0, new BigDecimal("20.000").compareTo(resp.injectionRateAfterMgM3()));
66	        // 加注量 = 100 m3 × 20 mg/m3 = 2000 mg
67	        assertEquals(0, new BigDecimal("2000.000").compareTo(resp.injectionDoseMg()));
68	
69	        long issues = count("SELECT COUNT(*) FROM adjustment_issue WHERE task_id = ?", resp.taskId());
70	        assertEquals(2, issues, "同一任务必须同事务下发 PRESSURE 与 INJECTION 两条指令");
