package com.example.starter.tank;

import java.math.BigDecimal;

/**
 * 储罐：绑定门站的合成加臭剂储罐。
 *
 * @param id              储罐ID
 * @param stationId       绑定门站ID（一个门站至多一个储罐）
 * @param tankCode        储罐唯一编码
 * @param capacityKg      罐容量 kg，三位小数
 * @param safetyReserveKg 安全储备 kg，0≤安全储备<容量
 * @param balanceKg       当前余额 kg，三位小数
 * @param reservedKg      预占中数量 kg（未执行/未取消计划合计）
 * @param version         乐观锁版本，从 1 开始，成功变更加 1
 */
public record Tank(Long id, Long stationId, String tankCode, BigDecimal capacityKg,
                   BigDecimal safetyReserveKg, BigDecimal balanceKg, BigDecimal reservedKg,
                   long version) {

    /**
     * 可用量 kg = 余额 − 预占中数量。
     */
    public BigDecimal availableKg() {
        return balanceKg.subtract(reservedKg);
    }
}

package com.example.starter.tank;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 受控加注计划：先预占所需量，预占后可用量不得低于安全储备（恰等允许）。
 *
 * @param id            计划ID
 * @param tankId        储罐ID
 * @param requestId     创建计划的幂等键
 * @param plannedAt     计划时刻（业务时间）
 * @param requiredQtyKg 计划预占量 kg
 * @param status        RESERVED/EXECUTED/CANCELLED/BLOCKED
 * @param actualQtyKg   回执实际消耗 kg，不得大于预占量；未执行为 null
 * @param executedAt    执行时刻，未执行为 null
 * @param cancelledAt   取消时刻，未取消为 null
 */
public record TankPlan(Long id, Long tankId, String requestId, LocalDateTime plannedAt,
                       BigDecimal requiredQtyKg, String status, BigDecimal actualQtyKg,
                       LocalDateTime executedAt, LocalDateTime cancelledAt) {
}

package com.example.starter.tank;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 补液单：唯一运输批号，两名不同交接人共同确认后原子入账。
 *
 * @param id                 补液单ID
 * @param tankId             储罐ID
 * @param transportBatchNo   唯一运输批号
 * @param quantityKg         补液数量 kg
 * @param concentrationMgM3  合成验收浓度 mg/m3，须在许可闭区间内
 * @param firstOperator      第一名交接人工号
 * @param secondOperator     第二名交接人工号，须与第一人不同
 * @param receivedAt         验收时刻（业务时间）
 */
public record TankRefill(Long id, Long tankId, String transportBatchNo, BigDecimal quantityKg,
                         BigDecimal concentrationMgM3, String firstOperator, String secondOperator,
                         LocalDateTime receivedAt) {
}

package com.example.starter.tank;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 待补液事件：预占后可用量低于安全储备时生成；补液入账后关闭可满足的事件，
 * 仅关闭不重发旧加注命令。
 *
 * @param id               事件ID
 * @param tankId           储罐ID
 * @param source           触发来源：PLAN 加注计划 / PRESSURE 压力联动
 * @param planId           触发计划ID，压力联动触发为 null
 * @param requiredQtyKg    触发时所需量 kg
 * @param deficitQtyKg     触发时缺口 kg
 * @param status           OPEN 待补液 / CLOSED 已可满足
